<?php
require_once __DIR__ . '/../config/auth.php';require_student();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$user=db()->prepare('SELECT email FROM users WHERE id=?');$user->execute([$_SESSION['student_id']]);$email=$user->fetchColumn();$stmt=db()->prepare('SELECT d.file_path,d.document_type FROM application_documents d JOIN applications a ON a.id=d.application_id WHERE d.id=? AND a.email=?');$stmt->execute([$id,$email]);$doc=$stmt->fetch();$full=$doc?realpath(__DIR__.'/../'.$doc['file_path']):false;$root=realpath(UPLOAD_DIR);if(!$full||!$root||!str_starts_with($full,$root.DIRECTORY_SEPARATOR)||!is_file($full)){http_response_code(404);exit('Document not found.');}header('X-Content-Type-Options: nosniff');header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.basename($full).'"');header('Content-Length: '.filesize($full));readfile($full);exit;
